mkdir -p tests/CheckoutPricing.UnitTests/Discounts && cat > tests/CheckoutPricing.UnitTests/Discounts/GoldDiscountTests.cs <<'E'
using System.Reflection;
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.Discounts;

public sealed class GoldDiscountTests
{
    // Scenario: Gold customer with a 100.00 subtotal pays 95.00.
    // No checkout API exists yet, so the test can only assert that one is present.
    [Fact]
    public void GoldCustomerWithSubtotal100PaysPayableTotal95()
    {
        var checkoutTypes = new[] { typeof(ApplicationMarker).Assembly, typeof(DomainMarker).Assembly }
            .SelectMany(a => a.GetExportedTypes())
            .Where(t => t.Name.Contains("Checkout", StringComparison.OrdinalIgnoreCase)
                     || t.Name.Contains("Pricing", StringComparison.OrdinalIgnoreCase))
            .ToList();

        Assert.True(checkoutTypes.Count > 0,
            "No checkout/pricing type exists, so a Gold customer's 100.00 subtotal cannot produce a payable total of 95.00.");
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | tail -15

